from __future__ import annotations
import asyncio
import copy
import json
from pathlib import Path
from pydantic import BaseModel, Field
from app.config import settings
from app.core.orchestrator import Orchestrator
from app.core.policy_loader import PolicyLoader
from app.llm.mock_client import MockClient
from app.models.domain import ClaimSubmission

# Default location of the per-case document images (one PNG per renderable
# document, named <case_id>_<file_id>.png). Generated by
# scripts/generate_eval_docs.py. Resolved relative to the repo root
# (app/eval/runner.py -> parents[2] == repo root) so it works from any cwd.
EVAL_DOCS_DIR = Path(__file__).resolve().parents[2] / "eval_docs"

class CaseResult(BaseModel):
    case_id: str
    case_name: str
    expected_decision: str | None
    produced_decision: str | None
    pipeline_status: str = "COMPLETED"
    approved_amount: int | None = None
    confidence: float | None = None
    passed: bool
    failures: list[str] = Field(default_factory=list)
    member_message: str = ""
    trace: dict = Field(default_factory=dict)

class EvalReport(BaseModel):
    cases: list[CaseResult]
    passed: int
    failed: int

def load_cases(cases_path: str | None = None) -> list[dict]:
    with open(cases_path or settings.test_cases_path) as f:
        return json.load(f)["test_cases"]


def case_summaries(cases_path: str | None = None) -> list[dict]:
    """Lightweight metadata for the UI to render one button per case."""
    out = []
    for c in load_cases(cases_path):
        out.append({
            "case_id": c["case_id"],
            "case_name": c["case_name"],
            "description": c.get("description", ""),
            "expected": c.get("expected", {}),
            "documents": [{"file_id": d["file_id"],
                           "file_name": d.get("file_name"),
                           "actual_type": d.get("actual_type")}
                          for d in c["input"].get("documents", [])],
        })
    return out


def find_case(case_id: str, cases_path: str | None = None) -> dict | None:
    return next((c for c in load_cases(cases_path) if c["case_id"] == case_id), None)


class EvalRunner:
    def __init__(self, orchestrator: Orchestrator):
        self.orch = orchestrator

    @classmethod
    def default(cls) -> "EvalRunner":
        loader = PolicyLoader.load(settings.policy_path)
        return cls(Orchestrator(loader=loader, llm=MockClient()))

    async def run_all(self, cases_path: str) -> EvalReport:
        with open(cases_path) as f:
            cases = json.load(f)["test_cases"]
        results = [await self.run_case(c) for c in cases]
        report = EvalReport(cases=results,
                            passed=sum(c.passed for c in results),
                            failed=sum(not c.passed for c in results))
        return report

    async def run_case(self, case: dict) -> CaseResult:
        """Deterministic path: the case's structured content is injected, so the
        extraction step takes the 'provided' branch and no LLM perception runs."""
        sub = ClaimSubmission.model_validate(case["input"])
        out = await self.orch.process(sub)
        return self._evaluate(case, out)

    async def run_all_live(self, cases_path: str, live_orch: Orchestrator,
                           sleep_s: float = 0.0, max_attempts: int = 1,
                           retry_cooldown_s: float = 0.0) -> EvalReport:
        """Run every case through the real vision pipeline, pausing `sleep_s`
        between cases to stay under the LLM provider's rate limit.

        Vision perception is stochastic and the free tier throttles under load,
        so a case can fail transiently (a degraded extraction, a missed blur). A
        case that fails is retried up to `max_attempts` times after a
        `retry_cooldown_s` pause — each case passes cleanly in isolation, so this
        heals provider-throttling noise without masking real logic errors."""
        cases = load_cases(cases_path)
        results: list[CaseResult] = []
        for i, c in enumerate(cases):
            r = await self.run_case_live(c, live_orch)
            attempt = 1
            while not r.passed and attempt < max_attempts:
                await asyncio.sleep(retry_cooldown_s)
                r = await self.run_case_live(c, live_orch)
                attempt += 1
            results.append(r)
            if sleep_s and i < len(cases) - 1:
                await asyncio.sleep(sleep_s)
        return EvalReport(cases=results,
                          passed=sum(c.passed for c in results),
                          failed=sum(not c.passed for c in results))

    async def run_case_live(self, case: dict, live_orch: Orchestrator,
                            docs_dir: Path = EVAL_DOCS_DIR) -> CaseResult:
        """Vision path: each document's injected content is replaced with the
        generated image bytes, forcing real LLM classification, extraction and
        name-matching through `live_orch`. Assertions stay strict — a vision
        misread surfaces honestly in `failures`."""
        sub = self._build_live_submission(case, docs_dir)
        out = await live_orch.process(sub)
        return self._evaluate(case, out)

    @staticmethod
    def live_images_for(case: dict, docs_dir: Path = EVAL_DOCS_DIR) -> list[str]:
        """file_ids of the case's documents that have a generated image on disk.
        Empty when the images are missing (e.g. not copied into a container) —
        used to fail loudly instead of silently degrading to the injected
        content (mock) path."""
        cid = case["case_id"]
        return [d["file_id"] for d in case["input"].get("documents", [])
                if (docs_dir / f"{cid}_{d['file_id']}.png").exists()]

    @staticmethod
    def _build_live_submission(case: dict, docs_dir: Path) -> ClaimSubmission:
        """Swap injected content for image bytes wherever an image exists. A
        document with no generated image keeps its provided content (so cases
        can mix vision-read and injected documents)."""
        data = copy.deepcopy(case["input"])
        cid = case["case_id"]
        for doc in data.get("documents", []):
            img = docs_dir / f"{cid}_{doc['file_id']}.png"
            if not img.exists():
                continue
            # Clear every test-path hint so DocVerifier/Extraction/Consistency
            # are driven purely by the image, not the fixture metadata.
            for hint in ("actual_type", "quality", "content", "patient_name_on_doc"):
                doc.pop(hint, None)
            doc["file_bytes"] = img.read_bytes()
            doc["mime_type"] = "image/png"
        return ClaimSubmission.model_validate(data)

    def _evaluate(self, case: dict, out) -> CaseResult:
        exp = case["expected"]
        failures: list[str] = []

        expected_decision = exp.get("decision")
        produced = out.decision.status.value if out.decision else None
        if produced != expected_decision:
            failures.append(
                f"decision: expected {expected_decision}, got {produced} "
                f"(pipeline_status={out.status})"
            )

        if "approved_amount" in exp and out.decision \
           and out.decision.approved_amount != exp["approved_amount"]:
            failures.append(f"amount: expected {exp['approved_amount']}, "
                            f"got {out.decision.approved_amount}")

        for reason in exp.get("rejection_reasons", []):
            if out.decision and reason not in out.decision.reasons:
                failures.append(f"missing rejection reason {reason}")

        cs = exp.get("confidence_score", "")
        if cs.startswith("above") and out.decision:
            bound = float(cs.split()[-1])
            if out.decision.confidence <= bound:
                failures.append(f"confidence {out.decision.confidence} not above {bound}")

        failures += self._check_system_must(case, out)

        return CaseResult(case_id=case["case_id"], case_name=case["case_name"],
                          expected_decision=expected_decision, produced_decision=produced,
                          pipeline_status=out.status,
                          approved_amount=out.decision.approved_amount if out.decision else None,
                          confidence=out.decision.confidence if out.decision else None,
                          passed=not failures, failures=failures,
                          member_message=out.member_message, trace=out.trace)

    def _check_system_must(self, case: dict, out) -> list[str]:
        """Mechanically checkable subset of the prose 'system_must' expectations."""
        f: list[str] = []
        cid, msg = case["case_id"], out.member_message
        if cid == "TC001" and not ("PRESCRIPTION" in msg and "HOSPITAL_BILL" in msg):
            f.append("TC001: message must name uploaded and required doc types")
        if cid == "TC002" and "blurry_bill.jpg" not in msg:
            f.append("TC002: message must name the unreadable file")
        if cid == "TC003" and not ("Rajesh Kumar" in msg and "Arjun Mehta" in msg):
            f.append("TC003: message must include both patient names")
        if cid == "TC005" and "2024-11-30" not in msg:
            f.append("TC005: message must state the eligibility date")
        if cid == "TC010" and "3600" not in msg:
            f.append("TC010: breakdown must show discount applied before co-pay")
        if cid == "TC011" and out.decision \
           and "manual review" not in out.decision.ops_summary.lower():
            f.append("TC011: must recommend manual review")
        return f

    _MOCK_PREAMBLE = (
        "> These cases run against the deterministic `MockClient` by design: "
        "`test_cases.json` ships document *content* as structured fixtures (no image "
        "files), so the eval validates the decision engine — policy checks, financial "
        "math, consistency, fraud, and the full trace — independently of the stochastic "
        "LLM perception layer. The real Gemini vision/extraction path is the same "
        "Orchestrator with the `LLMClient` swapped, and is exercised separately via the "
        "live API and the `@pytest.mark.live` tests.")

    _LIVE_PREAMBLE = (
        "> **Live vision run.** Each case is rendered to document image(s) "
        "(`eval_docs/<case_id>_<file_id>.png`, generated from `test_cases.json` by "
        "`scripts/generate_eval_docs.py`) and run through the **real Groq Llama-4 "
        "multimodal pipeline** — the LLM classifies each document, extracts its fields, "
        "and resolves patient-name equivalence. No structured content is injected; the "
        "`source: \"vision\"` on every extraction below is the evidence. All money and "
        "policy logic remains deterministic code reading `policy_terms.json`. Because "
        "perception is stochastic, assertions are strict and any mismatch is reported "
        "honestly. Runs are paced to respect the provider rate limit.")

    @staticmethod
    def _live_pipeline_summary(trace: dict) -> list[str]:
        """One-line-per-step evidence of the live path: status, duration, and the
        extraction source / detected document types."""
        rows = []
        for s in trace.get("steps", []):
            extras = []
            for c in s.get("checks", []):
                d = c.get("detail", {}) or {}
                if d.get("source"):
                    extras.append(f"{d.get('file_id')}:{d.get('doc_type')}={d['source']}")
                elif d.get("detected_type"):
                    extras.append(f"{d.get('file_id')}:{d['detected_type']}@{d.get('confidence')}")
            tail = ("  — " + ", ".join(extras)) if extras else ""
            rows.append(f"  - `{s['step']}` {s['status']} ({s['duration_ms']}ms){tail}")
        return rows

    @staticmethod
    def render_markdown(report: EvalReport, live: bool = False) -> str:
        title = ("# Eval Report — 12 Test Cases (Live Vision)" if live
                 else "# Eval Report — 12 Test Cases")
        lines = [title, "",
                 f"**Result: {report.passed}/{report.passed + report.failed} passed**", "",
                 EvalRunner._LIVE_PREAMBLE if live else EvalRunner._MOCK_PREAMBLE, ""]
        for c in report.cases:
            lines += [f"## {c.case_id} — {c.case_name}",
                      f"- Expected: `{c.expected_decision}` | Produced: `{c.produced_decision}`"
                      f" | **{'PASS' if c.passed else 'FAIL'}**"]
            if c.approved_amount is not None:
                lines.append(f"- Approved amount: ₹{c.approved_amount} | Confidence: {c.confidence}")
            if c.member_message:
                lines.append(f"- Member message: {c.member_message}")
            if c.failures:
                lines.append(f"- Mismatches: {'; '.join(c.failures)}")
            if live:
                lines += ["- Pipeline:"] + EvalRunner._live_pipeline_summary(c.trace)
            lines += ["", "<details><summary>Full trace</summary>", "", "```json",
                      json.dumps(c.trace, indent=2, default=str), "```",
                      "</details>", ""]
        return "\n".join(lines)
